import java.util.*;
import java.lang.*;
import java.io.*;

public class Ideone {

    static class WordCounter {
        boolean paren = false;
        int max = 0;
        int count = 0;
        int temp = 0;

        void process(char c) {
            if (c == '_') {
                if (paren && temp != 0) {
                    count++;
                } else if (temp > max) {
                    max = temp;
                }
                temp = 0;
            } else if (c == '(') {
                paren = true;
                if (temp > max) {
                    max = temp;
                }
                temp = 0;
            } else if (c == ')') {
                paren = false;
                if (temp > 0) {
                    count++;
                }
                temp = 0;
            } else {
                temp++;
            }
        }

        void finish() {
            if (temp > max) {
                max = temp;
            }
        }
    }

    public static void main(String[] args) throws java.lang.Exception {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        String a = sc.next();

        WordCounter wc = new WordCounter();
        for (int i = 0; i < n; i++) {
            wc.process(a.charAt(i));
        }
        wc.finish();

        System.out.println(wc.max + " " + wc.count);
    }
}
